import{_ as i}from"./chunks/gain_compression_diagram.BbKTQbFI.js";import{_ as o,C as r,o as t,c as s,j as a,a as c,E as d,al as l}from"./chunks/framework.7vp1BMOE.js";const G=JSON.parse('{"title":"Gain compression","description":"","frontmatter":{},"headers":[],"relativePath":"ko/features_fw/gain_compression.md","filePath":"ko/features_fw/gain_compression.md"}'),p={name:"ko/features_fw/gain_compression.md"};function _(m,e,h,f,u,g){const n=r("Badge");return t(),s("div",null,[e[0]||(e[0]=a("h1",{id:"gain-compression",tabindex:"-1"},[c("Gain compression "),a("a",{class:"header-anchor",href:"#gain-compression","aria-label":'Permalink to "Gain compression"'},"​")],-1)),d(n,{type:"tip",text:"PX4 v1.17"}),e[1]||(e[1]=l('<p>Automatic gain compression reduces the gains of the angular-rate PID whenever oscillations are detected. It monitors the angular-rate controller output through a band-pass filter to identify these oscillations.</p><p>This approach is a safe adaptive mechanism for stable aircraft: the PID gains remain unchanged when no oscillations are present, they are never increased beyond their nominal values, and they are bounded by a minimum limit.</p><p>Gain compression can help prevent actuator damage and even loss of the vehicle in cases such as airspeed-sensor failure (loss of airspeed scaling) or in-flight changes in dynamics (e.g.: CG shifts, inertia changes), or other failures that could cause the angular-rate loop to become oscillatory.</p><p><img src="'+i+'" alt="Gain compression diagram"></p><h2 id="사용법" tabindex="-1">사용법 <a class="header-anchor" href="#사용법" aria-label="Permalink to &quot;사용법&quot;">​</a></h2><p>Gain compression is enabled by default (<a href="./../advanced_config/parameter_reference#FW_GC_EN">FW_GC_EN</a>).</p><p>It should be disabled during fixed wing <a href="./../config_fw/pid_tuning_guide_fixedwing">manual tuning</a> to avoid over-tuning. It does not need to be disabled when autotuning.</p><h2 id="매개변수" tabindex="-1">매개변수 <a class="header-anchor" href="#매개변수" aria-label="Permalink to &quot;매개변수&quot;">​</a></h2><ul><li><a href="./../advanced_config/parameter_reference#FW_GC_EN">FW_GC_EN</a></li><li><a href="./../advanced_config/parameter_reference#FW_GC_GAIN_MIN">FW_GC_GAIN_MIN</a></li></ul>',9))])}const N=o(p,[["render",_]]);export{G as __pageData,N as default};
